-- E-05 backfill: FAQ translations x8 locales for the six owner-approved
-- English rows. NULL-guarded so studio edits are never clobbered; keyed
-- by exact English question text. Shape: { locale: { question, answer } }.

UPDATE "Faq" SET translations = '{"hi": {"question": "क्या आप पूरे भारत में डिलीवरी करते हैं, और कितना समय लगता है?", "answer": "हाँ — हम पूरे भारत में भेजते हैं। मेड-टू-ऑर्डर पीस बनने में आकार और जटिलता के अनुसार आमतौर पर 7–21 दिन लगते हैं (हर प्रोडक्ट पेज पर उसकी समयावधि दी है), और 3–7 दिन ट्रांज़िट के। शुरू करने से पहले हम WhatsApp पर आपके साथ सटीक समयावधि की पुष्टि करते हैं।"}, "gu": {"question": "શું તમે આખા ભારતમાં ડિલિવરી કરો છો, અને કેટલો સમય લાગે છે?", "answer": "હા — અમે આખા ભારતમાં મોકલીએ છીએ. મેડ-ટુ-ઓર્ડર પીસ બનતાં કદ અને જટિલતા પ્રમાણે સામાન્ય રીતે 7–21 દિવસ લાગે છે (દરેક પ્રોડક્ટ પેજ પર તેની સમયરેખા છે), ઉપરાંત ટ્રાન્ઝિટમાં 3–7 દિવસ. શરૂ કરતાં પહેલાં અમે WhatsApp પર તમારી સાથે ચોક્કસ સમયરેખા નક્કી કરીએ છીએ."}, "ar": {"question": "هل توصلون إلى جميع أنحاء الهند، وكم يستغرق ذلك؟", "answer": "نعم — نشحن إلى كل أنحاء الهند. تستغرق القطع المصنوعة حسب الطلب عادةً 7–21 يومًا للتصنيع حسب الحجم والتعقيد (كل صفحة منتج تعرض مدتها)، إضافة إلى 3–7 أيام للشحن. نؤكد المدة الدقيقة معك عبر WhatsApp قبل البدء."}, "es": {"question": "¿Entregan en toda la India y cuánto tarda?", "answer": "Sí — enviamos a toda la India. Las piezas hechas a pedido suelen tardar 7–21 días en elaborarse según el tamaño y la complejidad (cada página de producto muestra su plazo), más 3–7 días de tránsito. Confirmamos el plazo exacto contigo por WhatsApp antes de empezar."}, "de": {"question": "Liefern Sie in ganz Indien, und wie lange dauert es?", "answer": "Ja — wir versenden überall in Indien. Auftragsarbeiten brauchen je nach Größe und Komplexität in der Regel 7–21 Tage Fertigung (jede Produktseite zeigt ihren Zeitrahmen), plus 3–7 Tage Versand. Den genauen Zeitplan bestätigen wir vor Beginn mit Ihnen auf WhatsApp."}, "fr": {"question": "Livrez-vous dans toute l''Inde, et en combien de temps ?", "answer": "Oui — nous expédions partout en Inde. Les pièces sur commande demandent généralement 7 à 21 jours de fabrication selon la taille et la complexité (chaque page produit indique son délai), plus 3 à 7 jours de transport. Nous confirmons le délai exact avec vous sur WhatsApp avant de commencer."}, "zh": {"question": "你们在全印度配送吗？需要多长时间？", "answer": "是的 — 我们配送至印度全境。定制作品的制作周期通常为 7–21 天，视尺寸与复杂度而定（每个商品页都标注了时间线），另加 3–7 天运输时间。开始制作前，我们会在 WhatsApp 上与您确认确切时间。"}, "ja": {"question": "インド全土への配送は可能ですか？どのくらいかかりますか？", "answer": "はい — インド全土へ発送しています。オーダーメイド作品の制作は、サイズと複雑さにより通常7〜21日（各商品ページに目安を記載）、輸送に3〜7日かかります。制作開始前にWhatsAppで正確なスケジュールを確認いたします。"}}'::jsonb WHERE question = 'Do you deliver across India, and how long does it take?' AND translations IS NULL;
UPDATE "Faq" SET translations = '{"hi": {"question": "आप कैसे सुनिश्चित करते हैं कि मेरा पीस सुरक्षित पहुँचे?", "answer": "हर पीस पूरी तरह क्योर किया जाता है, कोनों को सुरक्षित कर, घने फोम और बबल रैप के साथ डबल-बॉक्स में पैक कर, फ्रैजाइल मार्क किया जाता है। टेबल जैसी बड़ी चीज़ें क्रेट में जाती हैं। अगर कुछ भी क्षतिग्रस्त पहुँचे, तो 48 घंटों के भीतर WhatsApp पर फ़ोटो भेजें और हम उसे सही करेंगे।"}, "gu": {"question": "મારો પીસ સુરક્ષિત પહોંચે તે તમે કેવી રીતે સુનિશ્ચિત કરો છો?", "answer": "દરેક પીસ સંપૂર્ણ ક્યોર થાય છે, ખૂણા સુરક્ષિત કરી, ગાઢ ફોમ અને બબલ રેપ સાથે ડબલ-બોક્સમાં પેક કરી, ફ્રેજાઇલ માર્ક થાય છે. ટેબલ જેવી મોટી વસ્તુઓ ક્રેટમાં જાય છે. કંઈ પણ ક્ષતિગ્રસ્ત પહોંચે તો 48 કલાકમાં WhatsApp પર ફોટા મોકલો અને અમે તેને બરાબર કરીશું."}, "ar": {"question": "كيف تضمنون وصول قطعتي بأمان؟", "answer": "كل قطعة تُعالج بالكامل، وتُحمى زواياها، وتُغلَّف في صندوقين مع فوم كثيف وأغلفة فقاعية، وتُوسم بأنها قابلة للكسر. القطع الكبيرة كالطاولات تُشحن في صناديق خشبية. إذا وصل أي شيء متضررًا، أرسل لنا الصور عبر WhatsApp خلال 48 ساعة وسنصحح الأمر."}, "es": {"question": "¿Cómo garantizan que mi pieza llegue segura?", "answer": "Cada pieza se cura por completo, se protegen sus esquinas, se embala en doble caja con espuma densa y plástico de burbujas, y se marca como frágil. Las piezas grandes, como mesas, viajan en cajones de madera. Si algo llega dañado, envíanos fotos por WhatsApp en un plazo de 48 horas y lo resolveremos."}, "de": {"question": "Wie stellen Sie sicher, dass mein Stück sicher ankommt?", "answer": "Jedes Stück wird vollständig ausgehärtet, an den Ecken geschützt, mit dichtem Schaumstoff und Luftpolsterfolie doppelt verpackt und als zerbrechlich markiert. Große Stücke wie Tische reisen in Holzkisten. Kommt etwas beschädigt an, senden Sie uns innerhalb von 48 Stunden Fotos per WhatsApp — wir machen es wieder gut."}, "fr": {"question": "Comment garantissez-vous que ma pièce arrive intacte ?", "answer": "Chaque pièce est entièrement polymérisée, ses angles protégés, emballée en double carton avec mousse dense et papier bulle, et marquée fragile. Les grandes pièces comme les tables voyagent en caisse. Si quelque chose arrive endommagé, envoyez-nous des photos sur WhatsApp sous 48 heures et nous arrangerons cela."}, "zh": {"question": "你们如何确保作品安全送达？", "answer": "每件作品都会完全固化、护角保护，用高密度泡棉和气泡膜双层装箱，并标注易碎。桌子等大件采用木箱运输。若有任何损坏，请在 48 小时内通过 WhatsApp 发送照片给我们，我们会妥善解决。"}, "ja": {"question": "作品が安全に届くよう、どのような対策をしていますか？", "answer": "すべての作品は完全に硬化させ、角を保護し、高密度フォームと気泡緩衝材で二重梱包のうえ、割れ物表示をしています。テーブルなどの大型作品は木箱で発送します。万一破損して届いた場合は、48時間以内にWhatsAppで写真をお送りください。誠実に対応いたします。"}}'::jsonb WHERE question = 'How do you make sure my piece arrives safely?' AND translations IS NULL;
UPDATE "Faq" SET translations = '{"hi": {"question": "कस्टम फ़ोटो पीस के लिए आपको कैसी फ़ोटो क्वालिटी चाहिए?", "answer": "आपके फ़ोन या कैमरे से ली गई शार्प, अच्छी रोशनी वाली फ़ोटो सबसे अच्छी रहती हैं — आदर्श रूप से 2000px या उससे चौड़ी, WhatsApp कंप्रेशन के बिना (डॉक्यूमेंट के रूप में भेजें, या हम अपलोड लिंक देंगे)। स्क्रीनशॉट और भारी फ़िल्टर वाली इमेज प्रिंट क्वालिटी घटाती हैं; हम हर फ़ोटो देखते हैं और ईमानदारी से बताते हैं अगर वह आपके पीस के साथ न्याय नहीं करेगी।"}, "gu": {"question": "કસ્ટમ ફોટો પીસ માટે તમને કેવી ફોટો ક્વોલિટી જોઈએ?", "answer": "તમારા ફોન કે કૅમેરાથી લીધેલા શાર્પ, સારા પ્રકાશવાળા ફોટા શ્રેષ્ઠ છે — આદર્શ રીતે 2000px કે તેથી પહોળા, WhatsApp કમ્પ્રેશન વિના (ડોક્યુમેન્ટ તરીકે મોકલો, અથવા અમે અપલોડ લિંક આપીશું). સ્ક્રીનશોટ અને ભારે ફિલ્ટરવાળી છબીઓ પ્રિન્ટ ક્વોલિટી ઘટાડે છે; અમે દરેક ફોટો ચકાસીએ છીએ અને પ્રામાણિકપણે કહીએ છીએ જો તે તમારા પીસને ન્યાય નહીં આપે."}, "ar": {"question": "ما جودة الصور المطلوبة للقطع المخصصة بالصور؟", "answer": "أفضل الصور هي الحادة الجيدة الإضاءة من هاتفك أو كاميرتك — يفضَّل بعرض 2000 بكسل أو أكثر، دون ضغط WhatsApp (أرسلها كمستند، أو نشاركك رابط رفع). لقطات الشاشة والصور كثيفة الفلاتر تقلل جودة الطباعة؛ نراجع كل صورة ونخبرك بصدق إن كانت لن تنصف قطعتك."}, "es": {"question": "¿Qué calidad de foto necesitan para piezas con foto personalizada?", "answer": "Las mejores son fotos nítidas y bien iluminadas directas de tu móvil o cámara — idealmente de 2000px o más de ancho, sin la compresión de WhatsApp (envíalas como documento, o te compartimos un enlace de subida). Las capturas de pantalla y las imágenes muy filtradas reducen la calidad de impresión; revisamos cada foto y te decimos con honestidad si no le hará justicia a tu pieza."}, "de": {"question": "Welche Fotoqualität brauchen Sie für individuelle Foto-Stücke?", "answer": "Am besten sind scharfe, gut belichtete Fotos direkt vom Handy oder von der Kamera — idealerweise 2000px oder breiter, ohne WhatsApp-Kompression (als Dokument senden, oder wir teilen einen Upload-Link). Screenshots und stark gefilterte Bilder mindern die Druckqualität; wir prüfen jedes Foto und sagen Ihnen ehrlich, wenn es Ihrem Stück nicht gerecht wird."}, "fr": {"question": "Quelle qualité de photo faut-il pour les pièces photo personnalisées ?", "answer": "Le mieux : des photos nettes et bien éclairées, directement de votre téléphone ou appareil — idéalement 2000px de large ou plus, sans compression WhatsApp (envoyez-les en document, ou nous partageons un lien d''upload). Les captures d''écran et images très filtrées réduisent la qualité d''impression ; nous examinons chaque photo et vous disons honnêtement si elle ne rendra pas justice à votre pièce."}, "zh": {"question": "定制照片作品需要什么样的照片质量？", "answer": "最好是手机或相机直出的清晰、光线充足的照片 — 理想宽度 2000px 以上，且未经 WhatsApp 压缩（请以文件形式发送，或我们提供上传链接）。截图和重度滤镜的图片会降低打印质量；我们会审查每张照片，如果它无法呈现您作品的最佳效果，我们会如实相告。"}, "ja": {"question": "写真入りカスタム作品には、どの程度の写真品質が必要ですか？", "answer": "スマホやカメラで撮ったままの、シャープで明るい写真が最適です — 理想は幅2000px以上、WhatsApp圧縮なし（ドキュメントとして送信いただくか、アップロードリンクをお送りします）。スクリーンショットや強いフィルターの画像は印刷品質を落とします。すべての写真を確認し、作品に見合わない場合は正直にお伝えします。"}}'::jsonb WHERE question = 'What photo quality do you need for custom photo pieces?' AND translations IS NULL;
UPDATE "Faq" SET translations = '{"hi": {"question": "मैं अपनी रेज़िन कला की देखभाल और सफ़ाई कैसे करूँ?", "answer": "नरम सूखे या हल्के नम माइक्रोफ़ाइबर कपड़े से धूल हटाएँ। पीलेपन से बचाने के लिए लंबे समय तक सीधी धूप से दूर रखें, लगातार गर्मी (गर्म बर्तन, रेडिएटर) से दूर रखें, और फंक्शनल पीस कभी न भिगोएँ — पोंछकर साफ़ करें और सुखाएँ। अल्कोहल और एसीटोन क्लीनर से बचें।"}, "gu": {"question": "મારી રેઝિન કલાની સંભાળ અને સફાઈ કેવી રીતે કરું?", "answer": "નરમ સૂકા કે સહેજ ભીના માઇક્રોફાઇબર કપડાથી ધૂળ સાફ કરો. પીળાશથી બચવા લાંબો સમય સીધા સૂર્યપ્રકાશથી દૂર રાખો, સતત ગરમી (ગરમ વાસણ, રેડિએટર)થી દૂર રાખો, અને ફંક્શનલ પીસ ક્યારેય પલાળો નહીં — લૂછીને સાફ કરો અને સૂકવો. આલ્કોહોલ અને એસિટોન ક્લીનર ટાળો."}, "ar": {"question": "كيف أعتني بقطعة الراتنج وأنظفها؟", "answer": "أزل الغبار بقطعة ميكروفايبر ناعمة جافة أو رطبة قليلًا. أبعد القطع عن أشعة الشمس المباشرة المطوّلة لتجنب الاصفرار، وعن الحرارة المستمرة (الأواني الساخنة، المدافئ)، ولا تنقع القطع العملية أبدًا — امسحها ونشفها. تجنب المنظفات الكحولية والأسيتون."}, "es": {"question": "¿Cómo cuido y limpio mi arte en resina?", "answer": "Quita el polvo con un paño de microfibra suave, seco o ligeramente húmedo. Mantén las piezas alejadas de la luz solar directa prolongada para evitar el amarilleo, lejos del calor sostenido (ollas calientes, radiadores), y nunca sumerjas las piezas funcionales — límpialas con un paño y sécalas. Evita limpiadores con alcohol y acetona."}, "de": {"question": "Wie pflege und reinige ich meine Harzkunst?", "answer": "Staub mit einem weichen trockenen oder leicht feuchten Mikrofasertuch entfernen. Vor längerer direkter Sonne schützen (Vergilbung), von dauerhafter Hitze fernhalten (heiße Töpfe, Heizkörper), und funktionale Stücke nie einweichen — feucht abwischen und trocknen. Alkohol- und acetonhaltige Reiniger vermeiden."}, "fr": {"question": "Comment entretenir et nettoyer mon œuvre en résine ?", "answer": "Dépoussiérez avec un chiffon microfibre doux, sec ou légèrement humide. Évitez l''exposition prolongée au soleil direct (jaunissement), la chaleur soutenue (plats chauds, radiateurs), et ne trempez jamais les pièces fonctionnelles — essuyez et séchez. Évitez les nettoyants à l''alcool et à l''acétone."}, "zh": {"question": "如何保养和清洁我的树脂艺术品？", "answer": "用柔软的干燥或微湿超细纤维布除尘。避免长时间阳光直射以防泛黄，远离持续热源（热锅、暖气片），功能性作品切勿浸泡 — 擦拭后晾干即可。避免使用含酒精和丙酮的清洁剂。"}, "ja": {"question": "レジンアートのお手入れ・お掃除はどうすればいいですか？", "answer": "柔らかい乾いた（または軽く湿らせた）マイクロファイバークロスでほこりを拭ってください。黄変を防ぐため長時間の直射日光を避け、継続的な熱（熱い鍋、ヒーター）から遠ざけ、実用品は決して水に浸けず、拭いて乾かしてください。アルコールやアセトン系クリーナーは避けてください。"}}'::jsonb WHERE question = 'How do I care for and clean my resin art?' AND translations IS NULL;
UPDATE "Faq" SET translations = '{"hi": {"question": "क़ीमत और भुगतान कैसे काम करते हैं?", "answer": "प्रोडक्ट पेज सांकेतिक प्राइस बैंड दिखाते हैं। हर पीस कस्टमाइज़ होता है, इसलिए आपका आकार, सामग्री और डिटेलिंग समझने के बाद अंतिम कोट WhatsApp पर तय होता है। भुगतान सीधे WhatsApp पर तय होता है — आमतौर पर शुरू करने के लिए एडवांस और डिस्पैच से पहले शेष राशि। वेबसाइट स्वयं कोई भुगतान नहीं लेती।"}, "gu": {"question": "કિંમત અને ચુકવણી કેવી રીતે કામ કરે છે?", "answer": "પ્રોડક્ટ પેજ સૂચક પ્રાઇસ બેન્ડ બતાવે છે. દરેક પીસ કસ્ટમાઇઝ થાય છે, એટલે તમારું કદ, સામગ્રી અને ડિટેલિંગ સમજ્યા પછી અંતિમ ક્વોટ WhatsApp પર નક્કી થાય છે. ચુકવણી સીધી WhatsApp પર ગોઠવાય છે — સામાન્ય રીતે શરૂ કરવા એડવાન્સ અને ડિસ્પેચ પહેલાં બાકીની રકમ. વેબસાઇટ પોતે કોઈ ચુકવણી લેતી નથી."}, "ar": {"question": "كيف يعمل السعر والدفع؟", "answer": "تعرض صفحات المنتجات نطاق سعر استرشادي. ولأن كل قطعة مخصصة، يُؤكَّد السعر النهائي عبر WhatsApp بعد فهم الحجم والخامات والتفاصيل. يُرتَّب الدفع مباشرة عبر WhatsApp — عادةً دفعة مقدمة للبدء والباقي قبل الشحن. الموقع نفسه لا يستقبل أي مدفوعات."}, "es": {"question": "¿Cómo funcionan el precio y el pago?", "answer": "Las páginas de producto muestran un rango de precio orientativo. Como cada pieza es personalizada, el presupuesto final se confirma por WhatsApp tras entender tu tamaño, materiales y detalles. El pago se acuerda directamente por WhatsApp — normalmente un anticipo para empezar y el resto antes del envío. La web en sí no procesa pagos."}, "de": {"question": "Wie funktionieren Preis und Bezahlung?", "answer": "Produktseiten zeigen eine Preisspanne zur Orientierung. Da jedes Stück individuell ist, wird das endgültige Angebot auf WhatsApp bestätigt, sobald Größe, Material und Detaillierung klar sind. Die Zahlung wird direkt über WhatsApp vereinbart — üblicherweise eine Anzahlung zu Beginn und der Rest vor dem Versand. Die Website selbst nimmt keine Zahlungen an."}, "fr": {"question": "Comment fonctionnent le prix et le paiement ?", "answer": "Les pages produit affichent une fourchette de prix indicative. Chaque pièce étant personnalisée, le devis final est confirmé sur WhatsApp une fois votre taille, vos matériaux et vos détails précisés. Le paiement s''organise directement sur WhatsApp — généralement un acompte pour commencer et le solde avant l''expédition. Le site lui-même n''encaisse aucun paiement."}, "zh": {"question": "价格与付款如何进行？", "answer": "商品页显示的是参考价格区间。由于每件作品均为定制，最终报价会在了解您的尺寸、材料和细节后通过 WhatsApp 确认。付款直接在 WhatsApp 上安排 — 通常先付定金开始制作，发货前付清余款。网站本身不收取任何付款。"}, "ja": {"question": "価格と支払いはどのようになっていますか？", "answer": "商品ページには目安の価格帯を表示しています。すべてオーダーメイドのため、サイズ・素材・ディテールを伺ったうえでWhatsAppにて最終見積りを確定します。お支払いもWhatsAppで直接調整します — 通常は着手時に前金、発送前に残金です。ウェブサイト自体では決済を行いません。"}}'::jsonb WHERE question = 'How do price and payment work?' AND translations IS NULL;
UPDATE "Faq" SET translations = '{"hi": {"question": "क्या मैं मेड-टू-ऑर्डर पीस वापस या एक्सचेंज कर सकता/सकती हूँ?", "answer": "कस्टम पीस खास आपके लिए बनते हैं, इसलिए मन बदलने पर वापसी नहीं होती। अगर आपका पीस क्षतिग्रस्त पहुँचे या तय की गई चीज़ से अलग हो, तो 48 घंटों के भीतर फ़ोटो के साथ WhatsApp पर संपर्क करें — हम मरम्मत, दोबारा निर्माण या उचित समाधान करेंगे।"}, "gu": {"question": "શું હું મેડ-ટુ-ઓર્ડર પીસ પરત કે એક્સચેન્જ કરી શકું?", "answer": "કસ્ટમ પીસ ખાસ તમારા માટે બને છે, એટલે મન બદલાવા પર પરત લેવાતા નથી. જો તમારો પીસ ક્ષતિગ્રસ્ત પહોંચે કે નક્કી કરેલાથી અલગ હોય, તો 48 કલાકમાં ફોટા સાથે WhatsApp પર સંપર્ક કરો — અમે રિપેર, ફરી બનાવટ કે યોગ્ય ઉકેલ કરીશું."}, "ar": {"question": "هل يمكنني إرجاع أو استبدال قطعة مصنوعة حسب الطلب؟", "answer": "القطع المخصصة تُصنع خصيصًا لك، لذلك لا نقبل الإرجاع بسبب تغيير الرأي. إذا وصلت قطعتك متضررة أو مختلفة عما اتفقنا عليه، تواصل معنا عبر WhatsApp خلال 48 ساعة مع الصور — وسنصلحها أو نعيد صنعها أو نحل الأمر بإنصاف."}, "es": {"question": "¿Puedo devolver o cambiar una pieza hecha a pedido?", "answer": "Las piezas personalizadas se elaboran únicamente para ti, así que no se aceptan devoluciones por cambio de opinión. Si tu pieza llega dañada o difiere de lo acordado, contáctanos por WhatsApp en un plazo de 48 horas con fotos y la repararemos, rehacemos o resolveremos con justicia."}, "de": {"question": "Kann ich ein auf Bestellung gefertigtes Stück zurückgeben oder umtauschen?", "answer": "Individuelle Stücke werden eigens für Sie gefertigt, daher gibt es keine Rückgabe bei Meinungsänderung. Kommt Ihr Stück beschädigt an oder weicht es vom Vereinbarten ab, kontaktieren Sie uns innerhalb von 48 Stunden mit Fotos per WhatsApp — wir reparieren, fertigen neu oder finden eine faire Lösung."}, "fr": {"question": "Puis-je retourner ou échanger une pièce faite sur commande ?", "answer": "Les pièces personnalisées sont créées uniquement pour vous ; les retours pour changement d''avis ne sont donc pas proposés. Si votre pièce arrive endommagée ou diffère de ce qui était convenu, contactez-nous sur WhatsApp sous 48 heures avec des photos — nous réparerons, referons ou trouverons une solution équitable."}, "zh": {"question": "定制作品可以退货或换货吗？", "answer": "定制作品专为您打造，因此不支持因改变主意而退货。若作品送达时有损坏或与约定不符，请在 48 小时内附照片通过 WhatsApp 联系我们 — 我们会维修、重做或公平解决。"}, "ja": {"question": "オーダーメイド作品の返品・交換はできますか？", "answer": "カスタム作品はお客様のためだけに制作するため、お気持ちの変化による返品は承っておりません。破損して届いた場合や、お約束した内容と異なる場合は、48時間以内に写真を添えてWhatsAppでご連絡ください。修理・作り直し・公正な解決で誠実に対応いたします。"}}'::jsonb WHERE question = 'Can I return or exchange a made-to-order piece?' AND translations IS NULL;
